ght:var(--s1);background:var(--line);flex:1;border-radius:var(--radius-small)}.progress-track .active{background:var(--accent)}form{margin-top:var(--s6)}.field{margin-bottom:var(--s5)}label{display:block;font-size:var(--fs-label);font-weight:var(--weight-bold);margin-bottom:var(--s2)}input{width:100%;height:var(--input-height);padding:var(--s3);color:var(--fg);background:var(--surface);border:var(--border) solid var(--input-line);border-radius:var(--radius-small);font-size:var(--fs-body)}input[aria-invalid=\"true\"]{border:var(--strong-border) solid var(--error)}.hint{font-size:var(--fs-note);color:var(--muted);margin-top:var(--s2)}.error{display:flex;align-items:flex-start;gap:var(--s2);font-size:var(--fs-note);color:var(--error);margin-top:var(--s2)}.error svg{width:var(--s5);height:var(--s5);margin-top:var(--s1)}.error-summary{background:var(--error-bg);color:var(--error);padding:var(--s3);border-left:var(--strong-border) solid var(--error);margin-top:var(--s5);font-size:var(--fs-note)}.code-input{font-family:var(--font-code);font-size:var(--fs-code);letter-spacing:var(--letter-code);padding-left:var(--s4)}.code-destination{color:var(--fg);font-weight:var(--weight-medium);display:block;margin-top:var(--s2)}.text-button{min-height:var(--target);padding:var(--s2) var(--s0);background:transparent;color:var(--accent);font-size:var(--fs-note);text-decoration:underline;text-underline-offset:var(--s1)}.warning{display:flex;gap:var(--s3);margin-top:var(--s6);padding-top:var(--s5);border-top:var(--border) solid var(--line);font-size:var(--fs-note);color:var(--muted)}.warning svg{margin-top:var(--s1)}.notice{font-size:var(--fs-note);color:var(--muted);margin-top:var(--s4)}.success-mark{width:var(--s9);height:var(--s9);display:grid;place-items:center;border-radius:var(--round);background:var(--success-bg);color:var(--success);margin:var(--s3) var(--s0) var(--s6)}.success-mark svg{width:var(--s7);height:var(--s7)}.account{margin:var(--s7) var(--s0);padding:var(--s5);border-top:var(--strong-border) solid var(--accent);border-bottom:var(--border) solid var(--line);background:var(--surface)}.account h2{font-size:var(--fs-body);font-weight:var(--weight-bold);margin-bottom:var(--s1)}.account .account-owner{color:var(--muted);font-size:var(--fs-note)}dl{display:grid;grid-template-columns:1fr 1fr;gap:var(--s4);font-size:var(--fs-note);margin:var(--s5) var(--s0) var(--s0)}dt{color:var(--muted)}dd{margin:var(--s1) var(--s0) var(--s0);font-size:var(--fs-note);font-variant-numeric:tabular-nums}.done-note{margin-top:var(--s5);font-size:var(--fs-body);color:var(--muted)}dialog{width:calc(100% - var(--s7));max-width:var(--dialog-width);max-height:calc(100svh - var(--s7));margin:auto;padding:var(--s6);border:var(--border) solid var(--line);border-radius:var(--radius-large);background:var(--bg);color:var(--fg);box-shadow:var(--shadow);overflow:auto}dialog::backdrop{background:var(--scrim)}dialog h2{font-size:var(--fs-title);line-height:var(--lh-title);font-weight:var(--weight-medium);letter-spacing:var(--letter-heading);margin-bottom:var(--s4)}dialog p{font-size:var(--fs-body);color:var(--muted)}.phone{margin:var(--s6) var(--s0);background:var(--surface);border-top:var(--border) solid var(--line);border-bottom:var(--border) solid var(--line);padding:var(--s4) var(--s0)}.phone a{display:flex;align-items:center;gap:var(--s2);font-size:var(--fs-body);font-weight:var(--weight-bold);min-height:var(--target)}.phone .hint{margin-top:var(--s0)}dialog .warning{margin:var(--s5) var(--s0)}.sr-only{position:absolute;width:var(--border);height:var(--border);padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}
@media(min-width:700px){#app{border-inline:var(--border) solid var(--line);padding-inline:var(--s8)}main{min-height:calc(100svh - var(--header-height) - var(--s9))}}
@media(max-width:350px){#app{padding-inline:var(--s5)}.header{min-height:var(--s9);padding-block:var(--s3)}main{padding-top:var(--s5)}.welcome h1{font-size:var(--fs-title)}.steps{margin-block:var(--s6)}.steps li{padding-block:var(--s4)}.brand{font-size:var(--fs-code)}.help-button{padding-inline:var(--s2)}dialog{padding:var(--s5)}}
@media(prefers-reduced-motion:no-preference){button,a,input{transition:background-color var(--duration) var(--ease),outline-offset var(--duration) var(--ease)}}
