cat > outputs/app/app.js <<'EOF'
(() => {
'use strict';
const bank = window.EVAL_FIXTURES.bank;
const root = document.getElementById('app');
const params = new URLSearchParams(location.search);
const media = matchMedia('(prefers-color-scheme: dark)');
const theme = params.get('theme');
function applyTheme(){document.documentElement.dataset.theme = /"'^(light|dark)$/.test(theme) ? theme : media.matches ? '"'dark' : 'light';}
applyTheme();media.addEventListener('change',applyTheme);
document.documentElement.dataset.display = params.get('display') === 'tv' ? 'tv' : 'laptop';
let name = '', mobile = '', code = '', detailsErrors = false, codeError = '', resent = false;
let state = params.get('screen') || 'welcome';
if ("'!['"'welcome','details','details-error','code','code-error','help','done'].includes(state)) state='welcome';
if(state==='details-error')detailsErrors=true;
if(state==='code-error')codeError='That code is not right. Check your text message and try again.';
const directHelp=state==='help';if(directHelp)state='code';
const icons={arrow:'<path d=\"m14 6-6 6 6 6\"/>',right:'<path d=\"m9 6 6 6-6 6\"/>',help:'<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M9.8 9a2.3 2.3 0 0 1 4.4 1c0 1.5-2.2 1.8-2.2 3.5M12 17h.01\"/>',shield:'<path d=\"m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z\"/><path d=\"m8 12 3 3 5-6\"/>',check:'<path d=\"m5 12 4 4L19 6\"/>',phone:'<path d=\"M8 3H4v4c0 7 6 13 13 13h4v-4l-5-2-2 2c-3-1-5-3-6-6l2-2z\"/>',error:'<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v6m0 4h.01\"/>'};
const svg=(key)=>"'`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[key]}</svg>`;
const escape=(value)=>String(value).replace(/[&<>"'"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));
const step=()=>state.startsWith('details')?1:state==='done'?3:2;
const progress=()=>"'`<div class="progress"><span>Step ${step()} of 3</span><span class="progress-track" aria-hidden="true">${[1,2,3].map(i=>`<i class="${i<=step()?'"'active':''}\"></i>"'`).join('"'')}</span></div>"'`;
const warning=()=>`<aside class="warning">${svg('"'shield')}<p>"'${escape(bank.warning)}</p></aside>`;
function errorText(id,text){return `<p id="${id}" class="error">${svg('"'error')}<span>"'${text}</span></p>`;}
function welcome(){return `<main class="welcome"><p class="eyebrow">Welcome to mobile banking</p><h1>Your bank,<br>where you are.</h1><p class="intro">The Harbour you know, with you at home and on the go.</p><ol class="steps"><li><span class="step-number" aria-hidden="true">1</span><span>Your details<span class="step-sub">Your name and mobile number</span></span></li><li><span class="step-number" aria-hidden="true">2</span><span>A quick security check<span class="step-sub">A code by text message</span></span></li><li><span class="step-number" aria-hidden="true">3</span><span>Ready to bank<span class="step-sub">Take things at your own pace</span></span></li></ol><div class="welcome-actions"><button class="primary" data-action="start">Let’s get started ${svg('"'right')}</button><p class=\"reassurance\">"'${svg('"'help')}A person can help at any step.</p></div></main>"'`;}
function details(){const ne=detailsErrors&&!validName(name),me=detailsErrors&&!validMobile(mobile);return `<main><button class="back" data-action="back">${svg('"'arrow')}Back</button>"'${progress()}<h1 tabindex="-1">First, your details</h1><p class="intro">Use the name and mobile number you gave us at the branch.</p><form id="details-form" novalidate><div class="field"><label for="full-name">Full name</label><input id="full-name" name="name" autocomplete="name" value="${escape(name)}" aria-invalid="${ne}" ${ne?'"'aria-describedby=\"name-error\"':''}>"'${ne?errorText('"'name-error','Enter your full name, as it appears on your account.'):''}</div><div class=\"field\"><label for=\"mobile\">Mobile number</label><input id=\"mobile\" name=\"mobile\" type=\"tel\" inputmode=\"tel\" autocomplete=\"tel\" value=\""'${escape(mobile)}" aria-invalid="${me}" aria-describedby="mobile-hint${me?'"' mobile-error':''}\"><p class=\"hint\" id=\"mobile-hint\">A UK mobile number, starting 07 or +44.</p>"'${me?errorText('"'mobile-error','Enter a valid UK mobile number, including all digits.'):''}</div><button class=\"primary\" type=\"submit\">Continue "'${svg('"'right')}</button></form><p class=\"notice\">Your details are used only for this setup.</p></main>"'`;}
function codeScreen(){const ending=mobile?mobile.replace(/'"\\D/g,'').slice(-3):bank.mobileEnding;return "'`<main><button class="back" data-action="back">${svg('"'arrow')}Back</button>"'${progress()}<h1 tabindex="-1">Check your mobile</h1><p class="intro">Enter the ${bank.codeLength}-digit code from your text message.<span class="code-destination">Mobile number ending ${escape(ending)}</span></p><form id="code-form" novalidate><div class="field"><label for="code">${bank.codeLength}-digit code</label><input class="code-input" id="code" name="code" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="${bank.codeLength}" pattern="[0-9]{${bank.codeLength}}" value="${escape(code)}" aria-invalid="${!!codeError}" aria-describedby="code-hint${codeError?'"' code-error':''}\"><p class=\"hint\" id=\"code-hint\">Keep this code private.</p>"'${codeError?errorText('"'code-error',codeError):''}</div><button class=\"primary\" type=\"submit\">Confirm code "'${svg('"'right')}</button></form><button class=\"text-button\" data-action=\"resend\">Request a new code</button><p class=\"hint\" id=\"resend-status\" role=\"status\">"'${resent?'"'New code requested. In this practice setup, no text is sent.':''}</p>"'${warning()}<p class="notice">Practice setup: no text message is sent.</p></main>`;}
function done(){return `<main><div class="success-mark">${svg('"'check')}</div><p class=\"eyebrow\">Step 3 of 3 · Complete</p><h1 tabindex=\"-1\">You’re ready,<br>"'${escape(name.trim().split(/'"\\s+/)[0]||bank.customer.split(' ')[0])}.</h1><p class=\"intro\">You’ve finished the practice setup for mobile banking.</p><section class=\"account\" aria-label=\"Your example account\"><h2>"'${escape(bank.accountName)}</h2><p class="account-owner">${escape(name||bank.customer)}</p><dl><div><dt>Sort code</dt><dd>${escape(bank.sortCode)}</dd></div><div><dt>Account number</dt><dd>${escape(bank.accountNumber)}</dd></div></dl></section><p class="done-note">Your branch is still here for you. So are we, whenever you need a hand.</p><button class="secondary" data-action="finish" style="margin-top:var(--s7)">Finish</button></main>`;}
function render(focus=false){root.innerHTML=`<header class="header"><div class="brand" aria-label="${escape(bank.name)}"><svg viewBox="0 0 36 36" aria-hidden="true"><path d="M4 28h28M7 23V12a11 11 0 0 1 22 0v11M13 23V13a5 5 0 0 1 10 0v10M7 18h6m10 0h6"/></svg>${escape(bank.name)}</div><button class="help-button" id="help-trigger" data-action="help">${svg('"'help')}Help</button></header>"'${state==='"'welcome'?welcome():state.startsWith('details')?details():state==='done'?done():codeScreen()}<footer class=\"footer\">Practice setup · Your real account is unchanged</footer><dialog aria-labelledby=\"help-title\" aria-describedby=\"help-intro\"><h2 id=\"help-title\" tabindex=\"-1\">A person can help</h2><p id=\"help-intro\">You don’t have to do this alone. Our team can talk you through each step.</p><div class=\"phone\"><p>Call Harbour</p><a href=\"tel:"'${bank.helpPhone.replace(/'"\\s/g,'')}\">"'${svg('"'phone')}"'${escape(bank.helpPhone)}</a><p class="hint">Or visit your usual branch.</p></div>${warning()}<button class="primary" data-action="close-help">Back to setup</button></dialog>`;
 if(focus){window.scrollTo(0,0);root.querySelector('"'h1').focus();}
 root.querySelector('#details-form')?.addEventListener('submit',submitDetails);
 root.querySelector('#code-form')?.addEventListener('submit',submitCode);
 const dialog=root.querySelector('dialog');dialog.addEventListener('close',()=>{document.body.style.overflow='';root.querySelector('#help-trigger').focus();if(new URLSearchParams(location.search).get('screen')==='help')updateUrl(state);});
 dialog.addEventListener('keydown',e=>{if(e.key"'!=='"'Tab')return;const items=[...dialog.querySelectorAll('a,button')];if(e.shiftKey&&(document.activeElement===items[0]||document.activeElement.id==='help-title')){e.preventDefault();items.at(-1).focus();}else if("'!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}});
}
function validName(v){return v.trim().length>=2&&/'"\\p{L}/u.test(v);}
function validMobile(v){return /"'^(?:07'"\\d{9}|\\+447\\d{9})"'$/.test(v.replace(/['"\\s()-]/g,''));}
function capture(){const n=root.querySelector('#full-name'),m=root.querySelector('#mobile'),c=root.querySelector('#code');if(n)name=n.value;if(m)mobile=m.value;if(c)code=c.value;}
function updateUrl(s){const url=new URL(location.href);url.searchParams.set('screen',s);history.replaceState({},'',url);}
function go(s){capture();state=s;updateUrl(s);render(true);}
function submitDetails(e){e.preventDefault();capture();detailsErrors=true;if(validName(name)&&validMobile(mobile)){code='';codeError='';go('code');}else{state='details-error';updateUrl(state);render();const first=root.querySelector('[aria-invalid=\"true\"]');first.focus();first.scrollIntoView({block:'center'});}}
function submitCode(e){e.preventDefault();capture();if(code===bank.testCode){codeError='';go('done');}else{codeError=code.length"'!==bank.codeLength?`Enter all ${bank.codeLength} digits from your text message.`:'"'That code is not right. Check your text message and try again.';state='code-error';updateUrl(state);render();const input=root.querySelector('#code');input.focus();input.select();}}
function openHelp(){capture();const dialog=root.querySelector('dialog');dialog.showModal();document.body.style.overflow='hidden';dialog.querySelector('h2').focus();}
root.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='start'){detailsErrors=false;go('details');}if(action==='back'){if(state.startsWith('details'))go('welcome');else{codeError='';go('details');}}if(action==='help')openHelp();if(action==='close-help')root.querySelector('dialog').close();if(action==='resend'){resent=true;root.querySelector('#resend-status').textContent='New code requested. In this practice setup, no text is sent.';}if(action==='finish'){name='';mobile='';code='';detailsErrors=false;codeError='';resent=false;go('welcome');}});
render();if(directHelp)openHelp();
})();
EOF"

